// Writes spec/llm-kit.md, the one file an author gives a chatbot so it can
// write or change a story: `dart run gamebook_engine:llm_kit [--check]`,
// run from engines/dart. With --check it only says whether the file is up
// to date (exit 1 if not), for CI.
import 'dart:io';

const _specDir = '../../spec';

const _intro = '''
<!-- Generated by `dart run gamebook_engine:llm_kit` from framework.md. Do not edit by hand. -->
# Gamebook Framework: kit for LLMs

Give this whole file to a chatbot (Claude, ChatGPT, any other) together with your request, for example "Write a short gamebook in this format about a lighthouse keeper, in English" or "Here is my story; add a fight in the cellar". Check what comes back with the validator (`dart run gamebook_engine:validate_story <file> --llm`) and paste its message back until there are no problems.

## Instructions for the model
You write gamebooks in the **Gamebook Framework** story format, defined in the reference below. Follow it exactly: the file is checked by a strict validator and any mistake is rejected.

1. Reply with **only** the JSON of the story file (`story.<lang>.json`), with no comments and no text around it. For a story in several languages, reply with one file per language, each in its own code block named after it; the files must have the same ids, the same number of choices in the same order, and differ only in text.
2. Use `"schema": 6`. A story valid in an older version is valid in 6.
3. Start from a preset (`"rules": { "preset": "fighting-fantasy" }` or `"d20-lite"`) unless asked for other rules. Its stats are listed in B4.
4. Give every page a short, readable id (`cellar`, `crypt-door`), and a `title`.
5. Make the story playable: every page reachable from `start`, at least one `victory` ending, no page the player cannot leave (except endings), and every item a choice needs (`has`) obtainable somewhere.
6. A page you cannot finish may be `"draft": true`; say so after the file.
7. When the author pastes validator messages back, fix every problem and reply with the **whole** corrected file.

## Mistakes that most often make a story invalid
- Any key not in the reference is an error. No comments, no extra fields, no trailing commas.
- Every page has **exactly one** of a non-empty `choices`, a `combat` or an `ending` (unless it is a draft).
- Every choice has **exactly one** of `to`, `check` or `table`, and every page id it names exists.
- Every stat, item, flag and journal entry used must exist: stats come from the rules (the preset, plus `rules.stats`), items from `items`, journal entries from `journal`.
- Dice are `NdM`, `NdM+K`, `NdM-K` or an integer, with no spaces: `2d6`, `1d20`, `1d6+1`.
- `{name}` in text needs `rules.creation.name: true`; `{stat}` must be a stat id. Write `{{` and `}}` for literal braces.
- In a random `table`, `upTo` values increase and the last one reaches the highest possible roll.
- A `vs-defense` enemy (preset `d20-lite`) needs a `defense`.
- `lang` must equal the language in the file name, and translations share one `id`.

## The format
''';

/// The kit for the spec in [specDir].
String buildKit([String specDir = _specDir]) {
  final spec = File('$specDir/framework.md').readAsStringSync();
  final partB = spec.indexOf('# Part B.');
  if (partB < 0) throw StateError('framework.md has no "# Part B."');
  // Headings move down one level so the kit has one top-level title.
  final reference = spec
      .substring(partB)
      .split('\n')
      .map((line) => line.startsWith('#') ? '#$line' : line)
      .join('\n');
  return '$_intro\n$reference';
}

/// Writes (or with `--check`, compares) the kit. Returns the exit code.
int runLlmKit(List<String> args, StringSink out) {
  final check = args.contains('--check');
  final target = File('$_specDir/llm-kit.md');
  final kit = buildKit();
  if (check) {
    final current = target.existsSync() ? target.readAsStringSync() : '';
    if (current == kit) return 0;
    out.writeln('spec/llm-kit.md is out of date: run llm_kit to regenerate it');
    return 1;
  }
  target.writeAsStringSync(kit);
  out.writeln('wrote ${target.path}');
  return 0;
}

void main(List<String> args) => exit(runLlmKit(args, stdout));
